// Opening names (ECO code + name) from the lichess-org/chess-openings dataset (CC0 1.0).
// The data is generated by scripts/build-openings.mjs into src/data/openings.json and is loaded
// lazily with a dynamic import(), so it lands in its own chunk and stays out of the main bundle.

export interface OpeningInfo {
  eco: string
  name: string
}

interface OpeningData {
  eco: string[]
  names: string[]
  /** Keyed by the first three FEN fields; values are [ecoIndex, nameIndex]. */
  pos: Record<string, [number, number]>
}

let book: Map<string, OpeningInfo> | null = null
let loading: Promise<void> | null = null

/** First three FEN fields (placement, side to move, castling): en passant and move counters are dropped so transpositions match. */
export function openingKey(fen: string): string {
  return fen.split(' ').slice(0, 3).join(' ')
}

/**
 * Load the opening book once; later calls reuse the same work. It never rejects: if the chunk
 * cannot be fetched (offline, say) the book stays empty, openingAt keeps returning null, and the
 * next call tries again.
 */
export function loadOpenings(): Promise<void> {
  if (book) return Promise.resolve()
  loading ??= import('../data/openings.json')
    .then((mod) => {
      const data = (mod.default ?? mod) as unknown as OpeningData
      const map = new Map<string, OpeningInfo>()
      for (const [key, [e, n]] of Object.entries(data.pos)) {
        map.set(key, { eco: data.eco[e] ?? '', name: data.names[n] ?? '' })
      }
      book = map
    })
    .catch(() => {
      loading = null
    })
  return loading
}

/** Opening for a position; null until loadOpenings() has finished, or when the position is not in the book. */
export function openingAt(fen: string): OpeningInfo | null {
  return book?.get(openingKey(fen)) ?? null
}

/**
 * Deepest book opening along a game. fens[0] is the start position and fens[i] the position
 * after ply i; `ply` is the index into fens. Null when no position is in the book.
 */
export function openingForPositions(fens: string[]): { info: OpeningInfo; ply: number } | null {
  for (let ply = fens.length - 1; ply >= 0; ply--) {
    const info = openingAt(fens[ply] as string)
    if (info) return { info, ply }
  }
  return null
}
